ALTER TABLE users ADD COLUMN IF NOT EXISTS rating numeric DEFAULT 5.0; ALTER TABLE users ADD COLUMN IF NOT EXISTS hourly_rate numeric DEFAULT 0.0; CREATE TABLE IF NOT EXISTS blocked_users (id uuid DEFAULT gen_random_uuid() PRIMARY KEY, blocker_id uuid REFERENCES users(id) ON DELETE CASCADE, blocked_id uuid REFERENCES users(id) ON DELETE CASCADE, created_at timestamptz DEFAULT now(), UNIQUE(blocker_id, blocked_id));
